export const PublicDocument: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => (
  <html lang="en">
    <head>
      <meta charSet="utf-8" />
      <meta name="viewport" content="width=device-width, initial-scale=1" />
      <title>Public Site</title>
      <link rel="modulepreload" href="/src/client.tsx" />
    </head>
    <body>
      {children}
      <script>import("/src/client.tsx")</script>
    </body>
  </html>
);

export const AdminDocument: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => (
  <html lang="en">
    <head>
      <meta charSet="utf-8" />
      <meta name="viewport" content="width=device-width, initial-scale=1" />
      <title>Admin Console</title>
      <link rel="modulepreload" href="/src/client.tsx" />
    </head>
    <body>
      {children}
      <script>import("/src/client.tsx")</script>
    </body>
  </html>
);

import type { LayoutProps } from "rwsdk/router";

export const PublicLayout: React.FC<LayoutProps> = ({ children }) => (
  <div data-testid="public-layout">
    <nav data-testid="public-nav">
      <a href="/">Home</a>
      <a href="/about">About</a>
    </nav>
    {children}
  </div>
);

import type { LayoutProps } from "rwsdk/router";

export const AdminLayout: React.FC<LayoutProps> = ({ children }) => (
  <div data-testid="admin-layout">
    <nav data-testid="admin-nav">
      <a href="/admin">Dashboard</a>
      <a href="/admin/users">Users</a>
      <a href="/admin/settings">Settings</a>
    </nav>
    {children}
  </div>
);

export const HomePage: React.FC = () => (
  <div data-testid="page-home">
    <h1>Welcome Home</h1>
  </div>
);

export const AboutPage: React.FC = () => (
  <div data-testid="page-about">
    <h1>About Us</h1>
  </div>
);

export const AdminDashboardPage: React.FC = () => (
  <div data-testid="page-admin-dashboard">
    <h1>Admin Dashboard</h1>
  </div>
);

export const AdminUsersPage: React.FC = () => (
  <div data-testid="page-admin-users">
    <h1>Manage Users</h1>
  </div>
);

export const AdminSettingsPage: React.FC = () => (
  <div data-testid="page-admin-settings">
    <h1>Admin Settings</h1>
  </div>
);

